INSERT INTO public.leyes (id, siglas, tipo, titulo, fecha_publicacion, url_original, temas_clave) VALUES ('014edf37-42d8-53c6-87a5-e6b2de31729c', 'PEMEX-JUJO-RTS-2026', 'convocatoria', 'Convocatoria de PEMEX para motobombas en la Batería Jujo y mantenimiento de equipos de extracción en la Región Terrestre Sur', '2026-11-19', 'https://sidof.segob.gob.mx/notas/5804408', ARRAY['Contratación de PEMEX', 'Extracción', 'DEE-CAT-B-GCEE-500-106688-26-1', 'DEE-CAT-S-GCEE-500-106680-26-1']);
INSERT INTO public.articulos (id, ley_id, orden, identificador, titulo_nombre, tipo_articulo, contenido) VALUES ('89fe0eb1-e7e0-5ac9-a2c7-53a43cf92391', '014edf37-42d8-53c6-87a5-e6b2de31729c', 1, 'Convocatoria y fundamento', 'Convocatoria de PEMEX para motobombas en la Batería Jujo y mantenimiento de equipos de extracción en la Región Terrestre Sur', 'convocatoria', '<p>PETROLEOS MEXICANOS</p>
<p>DIRECCION DE ADMINISTRACION Y SERVICIOS</p>
<p>SUBDIRECCION DE ABASTECIMIENTO</p>
<p>COORDINACION DE ABASTECIMIENTO PARA EXPLORACION Y EXTRACCION</p>
<p>GERENCIA DE CONTRATACIONES PARA EXPLORACION Y EXTRACCION</p>
<p>CONVOCATORIA</p>
<p>Con fundamento en los Artículos 134 de la Constitución Política de los Estados Unidos Mexicanos; Capítulo 13 del Tratado entre los Estados Unidos Mexicanos, los Estados Unidos de América y Canadá (T-MEC) y sus correlativos de cualquier Tratado de Libre Comercio (TLC) vigente con Título o Capítulo de Compras del Sector Público celebrados por los Estados Unidos Mexicanos; 78 y 80 de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos (la Ley); 13, 19 y 20 de las Disposiciones Generales de Contratación para Petróleos Mexicanos y sus Empresas Productivas Subsidiarias (Disposiciones), y Numerales IV.7 inciso b), IV.12.2, de las Políticas y Lineamientos para Abastecimiento, a nombre de Petróleos Mexicanos Empresa Pública del Estado, se convoca a los interesados a participar en los siguientes Concursos Abiertos Electrónicos Internacionales bajo la Cobertura de los Tratados de Libre Comercio.</p>');
INSERT INTO public.articulos (id, ley_id, orden, identificador, titulo_nombre, tipo_articulo, contenido) VALUES ('98e2dd5d-3979-5458-ae16-b841f0313806', '014edf37-42d8-53c6-87a5-e6b2de31729c', 2, 'DEE-CAT-B-GCEE-500-106688-26-1', 'Convocatoria de PEMEX para motobombas en la Batería Jujo y mantenimiento de equipos de extracción en la Región Terrestre Sur', 'convocatoria', '<p>No. DEE-CAT-B-GCEE-500-106688-26-1, que tiene por objeto el “Suministro, instalación y puesta en operación de motobombas para la planta de inyección de agua congénita de la Batería Jujo del Activo de Extracción Bellota Jujo”, de acuerdo con lo siguiente:</p>
<table><thead><tr><th>Evento</th><th>Fecha</th></tr></thead><tbody><tr><td>Visita al Sitio</td><td>24 de noviembre de 2026</td></tr><tr><td>Límite para que los participantes soliciten aclaraciones de dudas a las bases de contratación</td><td>26 de noviembre de 2026</td></tr><tr><td>Presentación y apertura de propuestas</td><td>22 de diciembre de 2026</td></tr><tr><td>Notificación del fallo y resultado del concurso</td><td>11 de enero de 2027</td></tr><tr><td colspan="2">Correo: email2workspace-prod+PEMEX+WS5980878798+1fcn@ansmtp.ariba.com</td></tr></tbody></table>');
INSERT INTO public.articulos (id, ley_id, orden, identificador, titulo_nombre, tipo_articulo, contenido) VALUES ('0e7219d4-d223-55f0-9fd7-223f79516c94', '014edf37-42d8-53c6-87a5-e6b2de31729c', 3, 'DEE-CAT-S-GCEE-500-106680-26-1', 'Convocatoria de PEMEX para motobombas en la Batería Jujo y mantenimiento de equipos de extracción en la Región Terrestre Sur', 'convocatoria', '<p>No. DEE-CAT-S-GCEE-500-106680-26-1, que tiene por objeto la “Rehabilitación y mantenimiento electromecánico a los equipos dinámicos de los Activos de la Subdirección de Extracción Región Terrestre Sur”, de acuerdo con lo siguiente:</p>
<table><thead><tr><th>Evento</th><th>Fecha</th></tr></thead><tbody><tr><td>Límite para que los participantes soliciten aclaraciones de dudas a las bases de contratación</td><td>25 de noviembre de 2026</td></tr><tr><td>Presentación y apertura de propuestas</td><td>22 de diciembre de 2026</td></tr><tr><td>Notificación del fallo y resultado del concurso</td><td>6 de enero de 2027</td></tr><tr><td colspan="2">Correo: email2workspace-prod+PEMEX+WS5981005170+9177@ansmtp.ariba.com</td></tr></tbody></table>');
INSERT INTO public.articulos (id, ley_id, orden, identificador, titulo_nombre, tipo_articulo, contenido) VALUES ('d021a51d-2413-577a-8d62-c67efe574a73', '014edf37-42d8-53c6-87a5-e6b2de31729c', 4, 'Condiciones comunes y firma', 'Convocatoria de PEMEX para motobombas en la Batería Jujo y mantenimiento de equipos de extracción en la Región Terrestre Sur', 'convocatoria', '<p>· Los concursos abiertos se llevarán a cabo a través de medios electrónicos en el Sistema Electrónico de Contrataciones (SISCeP)</p>
<p>· Unicamente podrán participar personas físicas o morales de nacionalidad mexicana o de países con los que los Estados Unidos Mexicanos tenga celebrado un Tratado de Libre Comercio vigente, con disposiciones en materia de Compras del Sector Público. Para el concurso DEE-CAT-B-GCEE-500-106688-26-1 los bienes propuestos deben ser originarios de México o de algún país con el que los Estados Unidos Mexicanos tenga celebrado un Tratado de Libre Comercio con disposiciones en materia de Compras del Sector Público.</p>
<p>· No podrán participar en los concursos las personas físicas o morales que se encuentran impedidas en términos de la Ley, su Reglamento y las Disposiciones, así como aquellas que se encuentren relacionadas por parentesco con la Presidenta de la República incluyendo para el caso de personas morales a los integrantes de su estructura accionaria o Beneficiarios finales.</p>
<p>· La información confidencial o reservada que presenten los participantes deberá ser así indicada por ellos con la finalidad que se le dé el tratamiento correspondiente en términos de la Ley General de Transparencia y Acceso a la Información Pública.</p>
<p>· Las Bases de Concurso, estarán a disposición de los interesados a partir de la publicación de la convocatoria en el Portal de Internet http://www.pemex.com/procura/procedimientos-de-contratacion/ concursosabiertos/Paginas/Pemex-Exploracion-y-Produccion.aspx. Los interesados en participar deberán remitir su manifiesto de interés en participar, al correo asociado al procedimiento de contratación.</p>
<p>· La firma del contrato se llevará a cabo por medios electrónicos a través de la plataforma e-firma de Pemex, mediante el uso de la Firma Electrónica Avanzada vigente que emita el Servicio de Administración Tributaria, o de manera autógrafa.</p>
<p>· Para la Substanciación del Procedimiento de Contratación, el suscrito, en mi calidad de Suplente por Ausencia de la Persona Titular de la Gerencia de Contrataciones para Exploración y Extracción, conforme al fundamento indicado más adelante, podré delegar la suscripción de documentos y actos de trámite de los procedimientos de contratación, de modo que surtirán plenos efectos, por lo quien participe voluntariamente en él, acepta dichos términos y representaciones.</p>
<p>VILLAHERMOSA, TABASCO, A 19 DE NOVIEMBRE DE 2026.</p>
<p>MARIO VALLE PAZ</p>
<p>SUBGERENTE</p>
<p>EN MI CARACTER DE SUPLENTE POR AUSENCIA DE LA PERSONA TITULAR DE LA GERENCIA</p>
<p>DE CONTRATACIONES PARA EXPLORACION Y EXTRACCION. EN EJERCICIO DE LAS FUNCIONES</p>
<p>QUE ME FUERON DELEGADAS POR LA SUBDIRECTORA DE ABASTECIMIENTO A TRAVES DEL OFICIO DAS-SA-234-2026, ASI COMO DE LAS FACULTADES QUE ME CONFIEREN LOS ARTICULOS 23, 229 FRACCION IV Y 327 DEL ESTATUTO ORGANICO DE LA EMPRESA PUBLICA DEL ESTADO, PETROLEOS MEXICANOS, PUBLICADO EN EL DIARIO OFICIAL DE LA FEDERACION EL 25 DE SEPTIEMBRE DE 2026</p>
<p>FIRMA ELECTRONICA.</p>
<p>(R.- 582529)</p>');
COMMIT;
